<template>
  <section class="flight-report-panel">
    <header><div><h3>飞行报告</h3><p>执行过程、实测数据与记录完整性</p></div><a-select :disabled="loading" v-if="report?.runs?.length > 1" v-model:value="selectedRun" style="min-width:220px" @change="reload"><a-select-option v-for="run in report.runs" :key="run.runId" :value="run.runId">{{ date(run.firstRecordAt) }}</a-select-option></a-select></header>
    <a-spin v-if="loading" />
    <a-alert v-if="error" type="warning" :message="error" show-icon />
    <template v-if="report">
      <div class="report-device">{{ report.aircraftName || '机型未记录' }} <span>{{ report.aircraftSn || '序列号未记录' }}</span></div>
      <div class="flight-metrics"><div v-for="item in metricRows" :key="item.label"><span>{{ item.label }}</span><strong>{{ item.value }}</strong></div></div>
      <a-alert v-if="report.quality?.missingFields?.length" type="info" :message="'缺失记录：' + report.quality.missingFields.join('、')" show-icon />
      <a-collapse :default-active-key="['quality', 'execution']" class="report-sections">
        <a-collapse-panel key="quality" header="记录完整性与计算口径"><p>记录 {{ report.quality?.recordCount || 0 }} 条；遥测间隙 {{ report.quality?.gapCount || 0 }} 处。</p><p v-for="(warning, i) in report.quality?.warnings || []" :key="i">{{ warning }}</p></a-collapse-panel>
        <a-collapse-panel key="execution" header="起降、电量与时间"><dl><template v-for="item in detailRows" :key="item.label"><dt>{{ item.label }}</dt><dd>{{ item.value }}</dd></template></dl></a-collapse-panel>
        <a-collapse-panel key="plan" header="计划参数（与实际飞行数据分开）"><dl><template v-for="item in plannedRows" :key="item.label"><dt>{{ item.label }}</dt><dd>{{ item.value }}</dd></template></dl></a-collapse-panel>
        <a-collapse-panel key="timeline" header="执行事件摘要"><div v-for="(item, i) in eventTimeline" :key="i" class="report-event"><time>{{ date(item.time) }}</time><strong>{{ item.title || item.state || item.kind }}</strong><p>{{ item.message || '已记录状态变化' }}</p></div><p v-if="!eventTimeline.length">没有持久化执行事件。可在原任务字段中查看创建、发布与执行请求时间。</p></a-collapse-panel>
        <a-collapse-panel key="fire" header="关联火情"><p>{{ report.relatedEvents?.association }}</p><p v-if="report.relatedEvents?.available">匹配 {{ report.relatedEvents.total }} 项。</p><div v-for="item in report.relatedEvents?.items || []" :key="item.eventId" class="report-event"><time>{{ date(item.eventTimestamp) }}</time><strong>{{ item.eventId }}</strong><p>状态 {{ item.status }}；级别 {{ item.fireLevel || '未记录' }}；置信度 {{ item.confidence ?? '未记录' }}</p></div><a-button v-if="report.relatedEvents?.hasMore" :loading="loading" @click="loadRelated('events')">加载更多火情</a-button></a-collapse-panel>
        <a-collapse-panel key="media" header="媒体与成果"><p>{{ report.media?.note || '媒体元数据未记录' }}</p><div v-for="item in report.media?.items || []" :key="item.fileId" class="report-event">{{ item.fileName }} · {{ date(item.createTime) }}</div><a-button v-if="report.media?.hasMore" :loading="loading" @click="loadRelated('media')">加载更多媒体</a-button></a-collapse-panel>
        <a-collapse-panel key="records" header="完整执行与遥测记录"><p>共 {{ report.records?.total || 0 }} 条；按采样时间排序。</p><div class="records-table"><table><thead><tr><th>时间</th><th>来源/事件</th><th>速度</th><th>相对高度</th><th>电量</th><th>飞行模式</th><th>垂直速度（NED 向下为正）</th><th>风速</th><th>坐标 / 卫星</th><th>事件与进度</th><th>绝对高度 / 定位</th><th>服务端接收时间</th></tr></thead><tbody><tr v-for="item in report.records?.items || []" :key="item.recordId"><td>{{ date(item.observedAt) }}</td><td>{{ item.source }} / {{ item.kind }}</td><td>{{ unit(item.speedMs, 'm/s') }}</td><td>{{ unit(item.relativeHeightM, 'm') }}</td><td>{{ unit(item.batteryPercent, '%') }}</td><td>{{ item.flightMode || '未记录' }}</td><td>{{ unit(item.verticalSpeedMs, 'm/s') }}</td><td>{{ unit(item.windSpeedMs, 'm/s') }}</td><td>{{ coordinate(item.latitude) }} / {{ coordinate(item.longitude) }}；{{ unit(item.gpsCount, '颗') }}</td><td>{{ item.eventState || '' }} {{ item.eventMessage || '' }}；进度 {{ unit(item.progressPercent, '%') }}；航点索引 {{ item.waypointIndex ?? '未记录' }}</td><td>{{ unit(item.altitudeM, 'm') }} / {{ item.positionFixed == null ? '未记录' : item.positionFixed ? '有效' : '未定位' }}</td><td>{{ date(item.receivedAt) }}</td></tr></tbody></table></div><a-pagination v-if="report.records?.total" v-model:current="page" :total="report.records.total" :page-size="50" :disabled="loading" :show-size-changer="false" size="small" @change="load" /></a-collapse-panel>
      </a-collapse>
    </template>
  </section>
</template>
<script setup lang="ts">
import { ref, computed, watch } from 'vue'
import request from '/@/api/http/request'
const props = defineProps<{ workspaceId: string; taskId: string }>()
const report = ref<any>(null); const loading = ref(false); const error = ref(''); const page = ref(1); const selectedRun = ref('')
let sequence = 0
const relationPages = { events: 1, media: 1 }
const endpoint = () => '/wayline/api/v1/workspaces/' + encodeURIComponent(props.workspaceId) + '/planned-waylines/' + encodeURIComponent(props.taskId) + '/flight-report'
const date = (value:any) => value ? new Date(value).toLocaleString('zh-CN', { hour12: false, timeZone: 'Asia/Shanghai' }) : '未记录'
const coordinate = (value:any) => value == null ? '未记录' : String(value)
const eventTimeline = computed(() => [...(report.value?.recordedMilestones || []), ...(report.value?.timeline || [])].sort((a, b) => a.time - b.time))
const unit = (value:any, suffix:string) => value == null ? '未记录' : String(Math.round(Number(value) * 100) / 100) + ' ' + suffix
const duration = (value:any) => value == null ? '未记录' : Math.floor(value / 60) + ' 分 ' + value % 60 + ' 秒'
const metricRows = computed(() => { const m = report.value?.metrics || {}; return [{ label: '飞行时长（实测起降区间）', value: duration(m.flightDurationSeconds) }, { label: '采样平均速度', value: unit(m.averageSpeedMs, 'm/s') }, { label: '最大采样速度', value: unit(m.maximumSpeedMs, 'm/s') }, { label: '最大相对高度', value: unit(m.maximumHeightM, 'm') }, { label: '电量消耗', value: unit(m.batteryConsumedPercentagePoints, '百分点') }, { label: '已记录轨迹距离', value: unit(m.observedDistanceM, 'm') }] })
const detailRows = computed(() => { const m = report.value?.metrics || {}; return [{ label: '起飞时间', value: date(m.takeoffAt) }, { label: '返航时间', value: date(m.returnAt) }, { label: '落地时间', value: date(m.landingAt) }, { label: '起飞电量', value: unit(m.takeoffBatteryPercent, '%') }, { label: '返航电量', value: unit(m.returnBatteryPercent, '%') }, { label: '落地电量', value: unit(m.landingBatteryPercent, '%') }, { label: '首条记录电量', value: unit(m.firstRecordedBatteryPercent, '%') }, { label: '末条记录电量', value: unit(m.lastRecordedBatteryPercent, '%') }, { label: '记录覆盖时长', value: duration(m.observedDurationSeconds) }, { label: '最小相对高度', value: unit(m.minimumHeightM, 'm') }, { label: '最大采样风速', value: unit(m.maximumWindSpeedMs, 'm/s') }] })
const plannedRows = computed(() => { const p = report.value?.planned || {}; return [{ label: '计划高度', value: unit(p.defaultHeight, 'm') }, { label: '速度上限', value: unit(p.maxSpeed, 'm/s') }, { label: '返航高度', value: unit(p.rthAltitude, 'm') }, { label: '安全起飞高度', value: unit(p.takeoffSecurityHeight, 'm') }, { label: '负载', value: p.payloadName || '未记录' }, { label: '航点数', value: p.totalWaypoints ?? '未记录' }, { label: '完成动作', value: p.finishAction || '未记录' }, { label: '失联策略', value: p.rcLostAction || '未记录' }] })
async function load () {
  const id = ++sequence; loading.value = true; error.value = ''
  try { const response:any = await request.get('/wayline/api/v1/workspaces/' + encodeURIComponent(props.workspaceId) + '/planned-waylines/' + encodeURIComponent(props.taskId) + '/flight-report', { params: { runId: selectedRun.value || undefined, page: page.value, pageSize: 50, snapshotRecordId: page.value > 1 ? report.value?.snapshotRecordId : undefined } }); if (id === sequence) { const next = response.data.data; if (report.value && report.value.snapshotRecordId === next.snapshotRecordId && report.value.runId === next.runId) { next.relatedEvents = report.value.relatedEvents; next.media = report.value.media } else { relationPages.events = 1; relationPages.media = 1 }; report.value = next; selectedRun.value = next.runId || '' } } catch (e:any) { if (id === sequence) error.value = e?.message || '飞行报告读取失败' } finally { if (id === sequence) loading.value = false }
}
async function loadRelated (kind: 'events' | 'media') {
  if (loading.value) return
  const id = sequence; const field = kind === 'events' ? 'relatedEvents' : 'media'; const nextPage = relationPages[kind] + 1
  loading.value = true; error.value = ''
  try { const response:any = await request.get(endpoint() + '/related', { params: { kind, runId: report.value.runId, snapshotRecordId: report.value.snapshotRecordId, page: nextPage, pageSize: 100 } }); if (id !== sequence) return; const result = response.data.data; report.value[field] = { ...report.value[field], ...result, items: report.value[field].items.concat(result.items) }; relationPages[kind] = nextPage } catch (e:any) { if (id === sequence) error.value = e?.message || '记录读取失败' } finally { if (id === sequence) loading.value = false }
}
function reload () { page.value = 1; load() }
watch(() => [props.workspaceId, props.taskId], () => { selectedRun.value = ''; report.value = null; reload() }, { immediate: true })
</script>
<style scoped>
.flight-report-panel{padding:20px;background:#f2f2f7;border-radius:14px;color:#1c1c1e;margin-bottom:24px;font-family:-apple-system,BlinkMacSystemFont,sans-serif}.flight-report-panel header{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.flight-report-panel h3{margin:0;color:#1c1c1e;font-size:22px}.flight-report-panel p{color:#636366;line-height:1.6;overflow-wrap:anywhere}.report-device{font-size:18px;margin:16px 0;overflow-wrap:anywhere}.report-device span{display:block;color:#636366;font-size:13px}.flight-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:20px 0}.flight-metrics>div{background:#fff;padding:16px;border-radius:12px;min-width:0}.flight-metrics span{display:block;color:#636366;font-size:13px}.flight-metrics strong{display:block;font-size:22px;margin-top:8px;overflow-wrap:anywhere}.report-sections{margin-top:20px;background:#fff}.flight-report-panel dl{display:grid;grid-template-columns:minmax(100px,1fr) minmax(0,2fr);gap:14px}.flight-report-panel dd{margin:0;overflow-wrap:anywhere}.flight-report-panel dt{color:#636366}.report-event{padding:12px 0;border-bottom:1px solid #e5e5ea;overflow-wrap:anywhere}.report-event time{display:block;color:#636366}.records-table{overflow:auto;max-height:460px;margin-bottom:16px}.records-table table{border-collapse:collapse;width:100%;font-size:12px}.records-table th,.records-table td{padding:10px;text-align:left;border-bottom:1px solid #e5e5ea;min-width:90px}@media(max-width:600px){.flight-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
